       "vi": "Em trai của bố, tôi gọi là chú. Em gái của mẹ, tôi gọi là dì. Bố mẹ của bạn tôi hả? Tôi hỏi tuổi trước. Nếu bố mẹ bạn ấy lớn tuổi hơn bố mẹ tôi, tôi gọi là bác. Nếu trẻ hơn, tôi gọi là cô, chú. Mẹ của bạn thân tôi năm nay sáu mươi tuổi, nên tôi gọi là bác. Bác ấy gọi tôi là cháu. Người lớn tuổi nhất nhà tôi là ông nội. Ông chín mươi hai tuổi rồi, nhưng ông vẫn đọc báo mỗi sáng."
