     "lines": [
      {
       "spk": "Cần Thơ",
       "vi": "Nhà tui ở Cần Thơ. Ở đây, nhiều nhà kêu con theo thứ. Con đầu là Hai, không phải là Một. Ba tui là con đầu, nên mấy em kêu ba tui là anh Hai. Em trai của ba, tui kêu là chú: chú Ba, chú Tư. Em út của ba, tui kêu là chú Út. Em gái của má, tui kêu là dì, dì Năm. Ba má của bạn tui, tui kêu là cô chú. Người lớn tuổi nhất nhà tui là ông nội, chín mươi tuổi. Ông nội cũng là con đầu, nên mấy em của ông kêu ông là anh Hai."
      },
      {
       "spk": "Đống Đa",
       "vi": "Tôi ở Hà Nội. Em trai của bố là chú, em gái của mẹ là dì. Bố mẹ của bạn tôi, tôi gọi là bác, vì hai bác lớn tuổi hơn bố mẹ tôi. Ở nhà tôi, ông bà nội lớn tuổi nhất. Ông tám mươi chín, bà tám mươi sáu. Tôi gọi là ông bà, xưng là cháu. Bạn cùng tuổi, tôi gọi là bạn, xưng là tôi hay mình."
      },
      {
       "spk": "Los Angeles",
       "vi": "Ở nhà, mình nói tiếng Anh nhiều. Nhưng mình vẫn gọi anh, chị bằng tiếng Việt. Em trai của ba, mình gọi là chú. Em gái của má, mình gọi là dì. Còn em trai của má thì khác, mình gọi là cậu. Ba má của bạn mình, mình gọi là cô chú. Người lớn tuổi nhất nhà mình là bà ngoại. Bà tám mươi bốn tuổi. Bà không nói tiếng Anh, nên mình nói tiếng Việt với bà. Bà nói mình nói tiếng Việt giỏi hơn năm ngoái."
      }
     ],
     "gloss": [],
