     "title": {
      "vi": "Giọng thật 2",
      "en": "OV family interviews, part 2"
     },
     "lead": "<p><em>Three more real speakers answer the same four questions. Listen first; the transcript opens after the audio ends. Add three rows to your </em>Real voices<em> table from H2, then say what is new in each answer. Last, mark the answer that is closest to your own family or to the words you learned (real or imagined; private, not shared).</em></p>",
     "after": "<div class=\"dv-table\"><table><tr><th></th><th>Em trai của bố</th><th>Em gái của mẹ</th><th>Bố mẹ của bạn</th><th>Người lớn tuổi nhất</th></tr><tr><td>Cần Thơ</td><td>…</td><td>…</td><td>…</td><td>…</td></tr><tr><td>Đống Đa</td><td>…</td><td>…</td><td>…</td><td>…</td></tr><tr><td>Los Angeles</td><td>…</td><td>…</td><td>…</td><td>…</td></tr></table></div><details class=\"dv-key\"><summary>Đáp án · Key</summary><div class=\"dv-table\"><table><tr><th></th><th>Em trai của bố</th><th>Em gái của mẹ</th><th>Bố mẹ của bạn</th><th>Người lớn tuổi nhất</th></tr><tr><td>Cần Thơ</td><td><strong>chú</strong> (by birth order: <em>chú Ba, chú Tư</em>; the youngest is <em>chú Út</em>)</td><td><strong>dì</strong> (<em>dì Năm</em>)</td><td><strong>cô chú</strong></td><td><strong>ông nội</strong>, 90</td></tr><tr><td>Đống Đa</td><td><strong>chú</strong></td><td><strong>dì</strong></td><td><strong>bác</strong></td><td><strong>ông nội</strong> 89, <strong>bà nội</strong> 86</td></tr><tr><td>Los Angeles</td><td><strong>chú</strong></td><td><strong>dì</strong></td><td><strong>cô chú</strong></td><td><strong>bà ngoại</strong>, 84</td></tr></table></div></details>\n<p><strong>What is new in each answer?</strong> → Cần Thơ: <strong>names by birth order</strong> (the eldest child is <em>Hai</em>, the youngest <em>Út</em>) · Đống Đa: <strong>bác</strong> for a friend’s parents who are older than her own, as the Hà Nội speaker said · Los Angeles: <strong>cậu</strong> = the mother’s younger brother (in the South, any brother of the mother is <em>cậu</em>; in the North an older one is <em>bác</em>).</p>\n<p><em>Word help: tui = tôi, kêu = gọi (Southern speech).</em></p>"
