     "titleVi": "Bốn bạn, bốn cách gọi",
     "titleEn": "texts 3–4 (Daniel; Đức Anh + his thank-you message)",
     "lead": "<p><strong>Segment 1 · Daniel (≈ 8 min).</strong> Listen first (L2 male voice 2).</p>",
     "after": "<p><em>Culture panel (English, outside the audio): in Korean a man calls his older brother</em> 형 <em>(hyeong) and older sister</em> 누나 <em>(nuna); a woman says</em> 오빠 <em>(oppa) and</em> 언니 <em>(eonni). Daniel’s mother’s sister is</em> 이모 <em>(imo), close to Vietnamese</em> dì.</p>\n<p><strong>Segment 2 · Đức Anh (≈ 11 min).</strong> Listen first (NM). Text 4 ends with the message he writes to cô Hằng that evening.</p>\n<p><strong>After all four texts: who had the hardest time, and why?</strong> Write one sentence (any language; HL route: in Vietnamese). No key; your teacher may use some answers (no names) as a warm-up in class 6.</p>"
