     "reveal": "<p><strong>Rule (≤ 120 words).</strong> To say your age: <strong>[the word for \"I\"] + number + tuổi</strong>. <em>Năm nay</em> (\"this year\") can go first or right after the pronoun. Add <strong>ạ</strong> when you talk to an elder; <em>rồi</em> adds \"already\" (<em>Bà tám mươi mốt tuổi rồi</em>). The word for \"I\" is the one that matches the person you talk to: <em>cháu</em> to bà nội, <em>em</em> to anh Đức Anh, <em>mình</em> to a friend, <em>chị/anh</em> to Tín. The answer is the same whether someone asked with <em>mấy</em> or <em>bao nhiêu</em>.</p><details class=\"dv-key\"><summary>Đáp án · Key</summary><p><strong>Check (say it).</strong> 1. To bà nội: you are 20. → <strong>Năm nay cháu hai mươi tuổi ạ.</strong> (<em>Cháu hai mươi tuổi ạ</em> accepted) · 2. To a classmate: you are 19. → <strong>Mình mười chín tuổi.</strong> · 3. To Tín: you are 18. → <strong>Anh / Chị mười tám tuổi.</strong></p></details>",
     "title": {
      "vi": "Khám phá",
      "en": "The answer frame: [pronoun] + (năm nay) + number + tuổi"
     },
     "lead": "<p><strong>Notice.</strong> Pairs get six answers from Ep 3a on strips. <em>What comes first? What can come before the number? What can come at the end?</em></p>"
