     "reveal": "<p class=\"dv-h\">Rule</p><ul><li><strong>\"You\"</strong> = what the other person is <strong>to you</strong>: <em>bà</em> (grandma’s generation), <em>chú / cô / bác</em> (your parents' generation), <em>anh / chị</em> (a bit older), <em>em</em> (younger), <em>bạn</em> (same age).</li><li><strong>\"I\"</strong> = what <strong>you are to them</strong>: <em>cháu</em> to bà, chú, cô, bác; <em>em</em> to anh, chị; <em>anh / chị</em> to em; <em>mình</em> to bạn.</li><li><strong>Same person, different words:</strong> chú Lộc is <em>ba</em> to Vy, <em>chú</em> to the guests, <em>anh</em> to cô Hằng.</li><li><strong>Insiders and guests:</strong> in many Southern families, grandchildren say <em>con</em> to their grandmother; guests say <em>cháu</em>. Both are fine.</li><li>Not sure? Ask the age, or ask: <em>Cháu gọi … là gì ạ?</em></li></ul>",
