     "lead": "<p><em>Structured input. No pronouns in these lines, so only</em> dạ, ạ <em>or their absence tells you the listener. Pick: 👵 bà nội or 🧑 a classmate.</em></p>",
     "after": "<p><strong>Rule panel · <em>thưa</em> (two uses).</strong></p>\n<ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Thưa bà, con mới về.\" aria-label=\"Nghe · Listen\">🔊</button> Thưa bà, con mới về.</li><li><button class=\"tts\" type=\"button\" data-say=\"Dạ thưa bà, cháu xin phép về ạ.\" aria-label=\"Nghe · Listen\">🔊</button> Dạ thưa bà, cháu xin phép về ạ.</li><li><button class=\"tts\" type=\"button\" data-say=\"Thưa bà, bà năm nay bao nhiêu tuổi ạ?\" aria-label=\"Nghe · Listen\">🔊</button> Thưa bà, bà năm nay bao nhiêu tuổi ạ?</li></ul>\n<p>1. <strong>Arriving or leaving</strong>: tell an elder you have come or are going (lines 1–2). 2. <strong>Opening a respectful question</strong> to an elder (line 3). <em>Thưa</em> is very polite and a little formal. Some families use it every day; others keep it for special moments. <em>Dạ</em> and <em>ạ</em> are enough in most talk with elders; you never lose points for leaving <em>thưa</em> out.</p>\n<p><strong>Marcus’s mistake:</strong> <em>Thưa ông</em> to chú Lộc was wrong twice: <em>ông</em> is for a grandfather, and <em>thưa</em> in a plain hello to a 52-year-old sounds stiff. <em>Cháu chào chú ạ</em> was all he needed.</p>",
