     "route": "hl",
     "lead": "<p><em>For heritage learners; anyone may try. Read the short text, then answer in Vietnamese. A model answer opens after you write.</em></p><ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Marcus rất lễ phép. Bạn ấy nói &quot;Thưa ông&quot; với chú Lộc. Nhưng chú Lộc năm mươi hai tuổi, chú là {{bố|ba}} của Vy, không phải là ông. Marcus lễ phép, nhưng xưng hô sai, nên chú Lộc cười.\" aria-label=\"Nghe · Listen\">🔊</button> Marcus rất <span class=\"gl\" lang=\"vi\">lễ phép</span> <span class=\"gl-g\">(polite, well-mannered)</span>. Bạn ấy nói \"Thưa ông\" với chú Lộc. Nhưng chú Lộc năm mươi hai tuổi, chú là {{bố|ba}} của Vy, không phải là ông. Marcus lễ phép, nhưng <span class=\"gl\" lang=\"vi\">xưng hô</span> <span class=\"gl-g\">(the words for \"you\" and \"I\")</span> sai, nên chú Lộc cười.</li><li><button class=\"tts\" type=\"button\" data-say=\"Nếu lần sau Marcus mang {{hoa quả|trái cây}} {{đến|tới}} nhà Vy, Marcus sẽ nói với bà nội: &quot;Cháu biếu bà ạ.&quot;\" aria-label=\"Nghe · Listen\">🔊</button> Nếu lần sau Marcus mang {{hoa quả|trái cây}} {{đến|tới}} nhà Vy, Marcus sẽ nói với bà nội: \"Cháu <span class=\"gl\" lang=\"vi\">biếu</span> <span class=\"gl-g\">(give (to an elder, respectful))</span> bà ạ.\"</li></ul>",
     "prompt": "Tại sao chú Lộc cười? Viết một câu, dùng từ \"lễ phép\" hoặc \"xưng hô\". Bạn mang {{hoa quả|trái cây}} {{đến|tới}} nhà Vy. Bạn nói gì với bà nội?",
     "minWords": 10,
     "model": "<p>1 <em>model:</em> <strong>Marcus lễ phép, nhưng xưng hô sai: chú Lộc không phải là ông.</strong> (any sentence that gives the reason with <em>lễ phép</em> or <em>xưng hô</em>)</p><p>2 <em>model:</em> <strong>Cháu biếu bà {{hoa quả|trái cây}} ạ.</strong> (<em>hoa quả</em> and <em>trái cây</em> both accepted; <em>Cháu biếu bà ít {{hoa quả|trái cây}} ạ</em> also natural; <em>Cháu gửi bà …</em> accepted)</p>",
