     "html": "<p><em>Round 1 (prompts, 4 min): the teacher replays three anonymous moments from the T2 rehearsal and asks \"Bà nội is 81. What could you say instead?\" Round 2 (recasts, 3 min): in a quick role-play the teacher repeats a learner’s line correctly without stopping the scene. Last 2 min: <strong>T2 briefing</strong> (scene groups, seats, cards, the on-deck chairs, the rubric).</em></p>\n<ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Bà ơi, bà nói lại được không?\" aria-label=\"Nghe · Listen\">🔊</button> Bà ơi, bà nói lại được không?</li><li><button class=\"tts\" type=\"button\" data-say=\"Dạ, bà nói lại được không ạ?\" aria-label=\"Nghe · Listen\">🔊</button> Dạ, bà nói lại được không ạ?</li><li><button class=\"tts\" type=\"button\" data-say=\"Dạ, cháu chưa hiểu ạ. Bà nói chậm lại một chút được không ạ?\" aria-label=\"Nghe · Listen\">🔊</button> Dạ, cháu chưa hiểu ạ. Bà nói chậm lại một chút được không ạ?</li></ul>\n<p><em>Focus: repair with</em> dạ … ạ <em>(</em>Dạ, bà nói lại giùm cháu được không ạ?<em> is also fine); and</em> hai mươi mốt<em>,</em> bốn mươi tư <em>in age answers.</em></p>"
