     "after": "<p><strong>Key (full list).</strong> Cô Phương 555-0172 · phòng 315 (<em>ba trăm mười lăm</em>) · Anh Đức Anh 555-0124 · phòng 418 · Lớp tiếng Việt · phòng 204 (<em>hai trăm linh tư / lẻ bốn</em>) · Vy 555-0119 · phòng 236 · Phòng sinh viên Việt Nam 555-0110 · phòng 107 (<em>một trăm linh bảy / lẻ bảy</em>) · Bác Tư 555-0165. In the check call the number is read digit by digit (<em>không một sáu năm</em>); <em>không một, sáu mươi lăm</em> and <em>không một sáu lăm</em> (a common compressed form in speech) are also accepted.</p>\n<p class=\"dv-h\"><strong>The check call.</strong></p>\n<ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Dạ, cháu chào bác Tư ạ. Số của bác là năm năm năm, không một sáu năm, phải không ạ?\" aria-label=\"Nghe · Listen\">🔊</button> <span class=\"spk-n\">Khách:</span> Dạ, cháu chào bác Tư ạ. Số của bác là năm năm năm, không một sáu năm, phải không ạ?</li><li><button class=\"tts\" type=\"button\" data-say=\"Phải rồi. Cháu là ai {{đấy|đó}}?\" aria-label=\"Nghe · Listen\">🔊</button> <span class=\"spk-n\">Bác Tư:</span> Phải rồi. Cháu là ai {{đấy|đó}}?</li></ul>\n<p><em>HL–L2 pairing: the L2 learner explains the number rule; the HL learner explains how a phone number is said at home.</em></p>",
