     "lead": "<p><em>The class family from story-asking (classes 1–2 and the H2 story). A and B each know half the ages. Ask, write, then build the age line together. Then decide together: what does the youngest call each member? If your class invented other ages, the teacher’s cards use them.</em></p>",
     "after": "<p><strong>Outcome.</strong> Age line: <strong>cụ ông 99 · ông 75 · bà 72 · bố 50 · mẹ 48 · con cả 21 · con mèo 15 · con út 6</strong>. The youngest calls them <strong>cụ · ông · bà · bố · mẹ · anh/chị</strong> (and the cat by its name).</p>"
