   "introHtml": "<p><em>Drama Studio pair cards for this unit (engine <code>drama.pairs</code>; the card names the pair, the learner fills the lines):</em></p>\n<div class=\"dv-table\"><table><tr><th>Card</th><th>Older person says \"you / I\"</th><th>Younger person says \"you / I\"</th><th>Note</th></tr><tr><td>bà ↔ cháu</td><td>cháu / bà</td><td>bà / cháu</td><td>bà nội (81) and a guest</td></tr><tr><td>chú ↔ cháu</td><td>con, cháu / chú</td><td>chú (<em>bác</em> OK) / cháu (<em>con</em> OK)</td><td>chú Lộc (52) and a guest</td></tr><tr><td>cô ↔ cháu</td><td>con, cháu / cô</td><td>cô (<em>dì, bác</em> OK) / cháu (<em>con</em> OK)</td><td>cô Hằng (49) and a guest</td></tr><tr><td>anh/chị ↔ em</td><td>em / anh, chị</td><td>anh, chị / em</td><td>a guest and Tín (14); anh Đức Anh (24) and a student</td></tr><tr><td>bạn ↔ mình</td><td>bạn / mình</td><td>bạn / mình</td><td>same age (Vy and Daniel)</td></tr><tr><td>ông ↔ cháu</td><td>cháu / ông</td><td>ông / cháu</td><td>the neighbour (about 70; T2 complication card)</td></tr></table></div>"
