     "lead": "<p class=\"dv-h\">T3 · <em>Lời cảm ơn gửi nhà Vy</em> (presentational): model → draft → final → feedback</p><p><em>Đức Anh’s message from narrow text 4 (</em>Bốn bạn, bốn cách gọi<em>, H5). Drag each label onto its sentence: <strong>address · thanks · one detail · sign-off</strong>.</em></p>",
     "after": "<details class=\"dv-key\"><summary>Đáp án · Key</summary><p>✗ \"Lần sau cháu xin phép đến chơi nữa ạ\" = thanks · it looks ahead to the next visit: that belongs to the sign-off.</p></details>\n<ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Bạn gửi lời cảm ơn đến ai? Bạn muốn cảm ơn về chuyện gì? Bạn thích gì nhất? Bạn nói chuyện với ai?\" aria-label=\"Nghe · Listen\">🔊</button> Bạn gửi lời cảm ơn đến ai? Bạn muốn cảm ơn về chuyện gì? Bạn thích gì nhất? Bạn nói chuyện với ai?</li></ul>\n<p><strong>Plan yours</strong> (notes, any language): <em>To whom?</em> (the whole family, one person, or an elder you choose, real or fictional) · <em>Thanks for what?</em> · <em>One detail you liked</em> · <em>How will you sign off?</em></p>"
