     "lead": "<p><em>Segment 1 · Draft (≈ 10 min). Segment 2 · Revise with the checklist (≈ 8 min). 5–8 sentences (≈ 50–90 syllables). Telex on. Your draft is saved; nothing is sent yet.</em></p>\n<p class=\"dv-h\"><strong>L2 route · frames (they fade: full frames → first words → keywords)</strong></p>\n<ul class=\"vi-lines\" lang=\"vi\"><li><button class=\"tts\" type=\"button\" data-say=\"Cháu chào … ạ.\" aria-label=\"Nghe · Listen\">🔊</button> Cháu chào ___ ạ.</li><li><button class=\"tts\" type=\"button\" data-say=\"Cháu cảm ơn … nhiều ạ.\" aria-label=\"Nghe · Listen\">🔊</button> Cháu cảm ơn ___ nhiều ạ.</li><li><button class=\"tts\" type=\"button\" data-say=\"… ngon lắm ạ. / Cháu rất vui được ….\" aria-label=\"Nghe · Listen\">🔊</button> ___ ngon lắm ạ. / Cháu rất vui được ___.</li><li><button class=\"tts\" type=\"button\" data-say=\"Lần sau cháu xin phép … ạ.\" aria-label=\"Nghe · Listen\">🔊</button> Lần sau cháu xin phép ___ ạ.</li><li><button class=\"tts\" type=\"button\" data-say=\"Cháu gửi lời cảm ơn ….\" aria-label=\"Nghe · Listen\">🔊</button> Cháu gửi lời cảm ơn ___.</li><li><button class=\"tts\" type=\"button\" data-say=\"Cháu ….\" aria-label=\"Nghe · Listen\">🔊</button> Cháu ___.</li></ul>\n<p><strong>HL route</strong> · write freely; try one sentence that is not in the model (<em>Cháu thích nhất …</em>; <em>Bà kể chuyện vui lắm ạ</em>).</p>"
